async function fresh(){const page=await browser.newPage({viewport:{width:1400,height:1000}});await page.goto(base);await page.locator('[angularMcpSource="open-snack"][data-angular-mcp-instance]').waitFor();await page.evaluate(()=>{delete (window as any).ng;});return page;}
const list=(page:Page)=>page.evaluate(()=>(window as any).__angularMcpBridge.list() as IntegrationDescriptor[]);
const execute=(page:Page,request:IntegrationRequest)=>page.evaluate(request=>(window as any).__angularMcpBridge.execute(request) as Promise<IntegrationResult>,request);
async function domTarget(page:Page,label:string){const nodes=(await list(page)).filter(node=>node.label===label&&node.provenance==='runtime-dom');assert.equal(nodes.length,1,JSON.stringify(nodes));return {instanceId:nodes[0].instanceId};}
test('real Material snackbar Undo is a distinct runtime-DOM action and invokes its original callback',async()=>{const page=await fresh();try{const source=(await list(page)).find(node=>node.sourceId==='open-snack')!;assert.equal(source.provenance,'compiler');assert.deepEqual(source.events,['click']);await execute(page,{operation:'activate',target:{instanceId:source.instanceId}});await page.getByRole('button',{name:'Undo'}).waitFor();const target=await domTarget(page,'Undo');const result=await execute(page,{operation:'activate',target});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));await page.waitForFunction(()=>document.querySelector('#undo')?.textContent==='1');assert.equal(await page.locator('#undo').textContent(),'1');}finally{await page.close();}});
test('library-owned confirmation buttons retain disabled guards and stale overlay identities are removed',async()=>{const page=await fresh();try{await execute(page,{operation:'activate',target:{sourceId:'open-confirm'}});await page.getByRole('dialog',{name:'Confirmation'}).waitFor();const disabled=await domTarget(page,'Disabled accept');const denied=await execute(page,{operation:'activate',target:disabled});assert.equal(denied.status,'not-dispatched');assert.equal(await page.locator('#accepted').textContent(),'0');const target=await domTarget(page,'Accept deletion');assert.equal((await execute(page,{operation:'activate',target})).status,'ui-dispatched');await page.getByRole('dialog',{name:'Confirmation'}).waitFor({state:'hidden'});assert.equal(await page.locator('#accepted').textContent(),'1');assert(!(await list(page)).some(node=>node.instanceId===target.instanceId));await assert.rejects(execute(page,{operation:'activate',target}),/stale/);}finally{await page.close();}});
test('public ARIA affordances and native anchors activate exact original DOM listeners',async()=>{const page=await fresh();try{for(const [label,expected]of [['Library menu item','menu'],['Library option','option'],['Library combobox','combobox'],['Library link','link']]){const target=await domTarget(page,label);const result=await execute(page,{operation:'activate',target});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));await page.waitForFunction(expected=>document.querySelector('#selected')?.textContent===expected,expected);}}finally{await page.close();}});
test('compiler registrations win and transparent source CVAs have no duplicate runtime-DOM control',async()=>{const page=await fresh();try{const descriptors=await list(page);assert.equal(descriptors.filter(node=>node.label==='Remove item').length,1);const field=descriptors.find(node=>node.sourceId==='source-check')!;assert.equal(field.provenance,'compiler');assert(!field.operations.includes('activate'),'A native checkbox delegate does not invent a pointer action on its CVA host');assert(!descriptors.some(node=>node.provenance==='runtime-dom'&&node.label==='Transparent checkbox'));const input=page.locator('library-check input');assert.equal(await input.getAttribute('data-angular-mcp-instance'),null);assert.equal((await execute(page,{operation:'fill',target:{instanceId:field.instanceId},value:true})).status,'ui-dispatched');assert.equal(await input.isChecked(),true);}finally{await page.close();}});
test('runtime-DOM semantic affordances retire when removed while observed Angular listeners remain explicit',async()=>{const page=await fresh();try{await page.addScriptTag({content:"const node=document.createElement('div');node.textContent='Passive library option';node.setAttribute('role','option');node.tabIndex=0;document.body.append(node);"});const target=await domTarget(page,'Passive library option');await page.getByRole('option',{name:'Passive library option'}).evaluate(node=>node.removeAttribute('role'));const passive=(await list(page)).find(node=>node.instanceId===target.instanceId)!;assert(passive);assert.deepEqual(passive.events,[]);assert.deepEqual(passive.operations,[]);assert.equal((await execute(page,{operation:'activate',target})).status,'not-dispatched');await page.getByText('Passive library option',{exact:true}).evaluate(node=>node.removeAttribute('tabindex'));assert(!(await list(page)).some(node=>node.instanceId===target.instanceId));const observed=await domTarget(page,'Library option');await page.getByRole('option',{name:'Library option'}).evaluate(node=>{node.removeAttribute('role');node.removeAttribute('tabindex');});const action=(await list(page)).find(node=>node.instanceId===observed.instanceId)!;assert(action.events.includes('click'));assert.equal((await execute(page,{operation:'activate',target:observed})).status,'ui-dispatched');assert.equal(await page.locator('#selected').textContent(),'option');await page.getByText('Library option',{exact:true}).evaluate(node=>node.remove());await assert.rejects(execute(page,{operation:'activate',target:observed}),/stale/);}finally{await page.close();}});
test('library-owned native file inputs advertise bounded JSON files without exposing file contents or clicks',async()=>{const page=await fresh();try{const field=(await list(page)).find(node=>node.label==='Library upload'&&node.tagName==='input'&&node.provenance==='runtime-dom');assert(field);assert.equal(field.tagName,'input');assert.equal(field.schema&&field.schema.type,'object');assert.deepEqual(field.events,[]);assert.deepEqual(field.operations,['fill']);assert.equal(field.value,undefined);assert.equal(await page.locator('label').filter({hasText:'Library upload'}).locator('input').getAttribute('data-angular-mcp-instance'),field.instanceId);}finally{await page.close();}});
test('a readonly focus delegate is not advertised as fillable and does not hide the public picker affordance',async()=>{const page=await fresh();try{const source=(await list(page)).find(node=>node.sourceId==='source-picker')!;assert.equal(source.schema,false);assert.equal(source.readonly,true);assert(!source.operations.includes('fill'));const denied=await execute(page,{operation:'fill',target:{instanceId:source.instanceId},value:'wrong'});assert.equal(denied.status,'not-dispatched');const target=await domTarget(page,'Readonly focus picker');const before=(await list(page)).find(node=>node.instanceId===target.instanceId)!;assert.equal(before.role,'combobox');assert.equal(before.clickOrigin,'native-ui');assert.equal(before.aria?.expanded,'false');const result=await execute(page,{operation:'activate',target});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('readonly-picker output').textContent(),'true');assert.equal((await list(page)).find(node=>node.instanceId===target.instanceId)!.aria?.expanded,'true');assert.equal(await page.locator('readonly-picker input').inputValue(),'Focused choice');}finally{await page.close();}});
test('readonly native ARIA listboxes retain exact runtime identities and original clicks',async()=>{const page=await fresh();try{const target=await domTarget(page,'Library listbox');const field=(await list(page)).find(node=>node.instanceId===target.instanceId)!;assert.equal(field.role,'listbox');assert.equal(field.provenance,'runtime-dom');assert.equal(field.clickOrigin,'native-ui');assert.equal(field.readonly,true);assert.equal((await execute(page,{operation:'fill',target,value:'Changed'})).status,'not-dispatched');const result=await execute(page,{operation:'activate',target});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('#selected').textContent(),'listbox');assert.equal(await page.getByRole('listbox',{name:'Library listbox'}).inputValue(),'Fixed choice');}finally{await page.close();}});

test('library-owned native text inputs are discoverable and dispatch original Angular input handlers',async()=>{const page=await fresh();try{const field=(await list(page)).find(node=>node.label==='Library verification digit')!;assert(field);assert.equal(field.provenance,'runtime-dom');assert.deepEqual(field.operations,['fill','activate','drag']);const result=await execute(page,{operation:'fill',target:{instanceId:field.instanceId},value:'7'});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('#digit').textContent(),'7');assert.equal((await execute(page,{operation:'activate',target:{instanceId:field.instanceId},event:'keydown',key:'Escape'})).status,'ui-dispatched');assert.equal(await page.locator('#dismissed').textContent(),'true');const tooLong=await execute(page,{operation:'fill',target:{instanceId:field.instanceId},value:'12'});assert.equal(tooLong.status,'not-dispatched');assert.equal(await page.locator('#digit').textContent(),'7');const protectedField=(await list(page)).find(node=>node.label==='Library protected input')!;assert.equal((await execute(page,{operation:'fill',target:{instanceId:protectedField.instanceId},value:'Changed'})).status,'not-dispatched');}finally{await page.close();}});
test('rich editing uses browser text editing and original input listeners without interpreting HTML',async()=>{const page=await fresh();try{const field=(await list(page)).find(node=>node.label==='Library rich editor')!;assert(field);assert.equal(field.kind,'control');assert.deepEqual(field.schema&&field.schema.type,'string');const value='<img src=x onerror=alert(1)> plain text';const result=await execute(page,{operation:'fill',target:{instanceId:field.instanceId},value});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.getByRole('textbox',{name:'Library rich editor'}).innerText(),value);assert.equal(await page.locator('[contenteditable] img').count(),0);assert.match((await page.locator('#edited').textContent())!,/&lt;img/);await page.getByRole('textbox',{name:'Library rich editor'}).evaluate(node=>node.addEventListener('beforeinput',event=>event.preventDefault()));const denied=await execute(page,{operation:'fill',target:{instanceId:field.instanceId},value:'Denied',mode:'input'});assert.match(denied.reason!,/refused/);assert.equal(await page.getByRole('textbox',{name:'Library rich editor'}).innerText(),value);}finally{await page.close();}});
test('hidden file inputs require a visible associated label and enforce file types, names, cardinality and size before mutation',async()=>{const page=await fresh();try{const field=(await list(page)).find(node=>node.label==='Library hidden PDF'&&node.tagName==='input')!;assert(field);assert.equal(field.visible,true);const target={instanceId:field.instanceId},file={name:'local.pdf',mimeType:'application/pdf',base64:Buffer.from('%PDF-1.4 synthetic').toString('base64')};const result=await execute(page,{operation:'fill',target,value:{files:[file]}});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('#files').textContent(),'local.pdf');assert.equal((await list(page)).find(node=>node.instanceId===target.instanceId)!.value,undefined);for(const value of [{files:[{...file,name:'../file.pdf'}]},{files:[{...file,mimeType:'text/plain',name:'file.txt'}]},{files:[file,file]},{files:[{...file,base64:'!!'}]},{files:[{...file,base64:Buffer.alloc(524289).toString('base64')}]}]){const refused=await execute(page,{operation:'fill',target,value});assert.equal(refused.status,'not-dispatched',JSON.stringify(refused));assert.equal(await page.locator('#files').textContent(),'local.pdf');}await page.locator('label[for="hidden-file"]').evaluate(node=>node.remove());assert.equal((await list(page)).find(node=>node.instanceId===target.instanceId)!.visible,false);assert.equal((await execute(page,{operation:'fill',target,value:{files:[file]}})).status,'not-dispatched');}finally{await page.close();}});

test('native label affordances preserve directive-style original click handlers',async()=>{const page=await fresh();try{const field=(await list(page)).find(node=>node.label==='Library label action')!;assert(field);assert.equal(field.provenance,'runtime-dom');const result=await execute(page,{operation:'activate',target:{instanceId:field.instanceId}});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('#accepted').textContent(),'1');}finally{await page.close();}});

test('activation settles finite UI exit animations before returning the next live catalog',async()=>{const page=await fresh();try{const field=(await list(page)).find(node=>node.label==='Animated overlay option')!;assert(field);const result=await execute(page,{operation:'activate',target:{instanceId:field.instanceId}});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.getByRole('button',{name:'Animated overlay option'}).count(),0);assert(!(await list(page)).some(node=>node.instanceId===field.instanceId));}finally{await page.close();}});

test('a recent exact UI trigger offers its hidden file input without guessing adjacent controls',async()=>{const page=await fresh();try{const file=(await list(page)).find(node=>node.label==='Triggered library file')!;assert(file);assert.equal(file.visible,false);const trigger=(await list(page)).find(node=>node.label==='Open library file picker')!;const chooser=page.waitForEvent('filechooser');assert.equal((await execute(page,{operation:'activate',target:{instanceId:trigger.instanceId}})).status,'ui-dispatched');await chooser;assert.equal((await list(page)).find(node=>node.instanceId===file.instanceId)!.visible,true);const result=await execute(page,{operation:'fill',target:{instanceId:file.instanceId},value:{files:[{name:'trigger.pdf',mimeType:'application/pdf',base64:Buffer.from('fixture').toString('base64')}]}});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('#files').textContent(),'trigger.pdf');assert.equal((await list(page)).find(node=>node.instanceId===file.instanceId)!.visible,false);}finally{await page.close();}});

test('new browser input paths retain production approvals, session checks and value redaction',async()=>{const page=await fresh();try{const nodes=await list(page),editor=nodes.find(node=>node.label==='Library rich editor')!,file=nodes.find(node=>node.label==='Library hidden PDF'&&node.tagName==='input')!;const policy={version:1 as const,allowedOrigins:[base],rules:[editor,file].map(node=>({sourceId:node.sourceId,label:node===editor?'Description':'Attachment',operations:['describe','fill','activate'] as ('describe'|'fill'|'activate')[]}))};const compiler=createRequire(import.meta.url)('typescript');const code=compiler.transpileModule(integrationProductionSource(policy,'browser-input-access-test'),{compilerOptions:{target:compiler.ScriptTarget.ES2022,module:compiler.ModuleKind.None}}).outputText;await page.addScriptTag({content:`var accessTest={approved:false,audit:[],session:{id:'local-test',subject:'operator',expiresAt:Date.now()+60000}};var __ngxMcpConnectAccess=async()=>({session:accessTest.session,origin:()=>location.origin,validateSession:async()=>accessTest.session,approve:async()=>accessTest.approved,audit:event=>accessTest.audit.push(event)});`+code});await page.waitForFunction(()=>(window as any).__angularMcpBridge.accessStatus().ready);const editorTarget={instanceId:editor.instanceId},fileTarget={instanceId:file.instanceId},attachment={files:[{name:'private.pdf',mimeType:'application/pdf',base64:Buffer.from('PRIVATE FILE DATA').toString('base64')}]};await assert.rejects(execute(page,{operation:'fill',target:editorTarget,value:'PRIVATE TEXT'}),/approval-denied/);await assert.rejects(execute(page,{operation:'fill',target:fileTarget,value:attachment}),/approval-denied/);assert.equal(await page.locator('#edited').textContent(),'');assert.equal(await page.locator('#files').textContent(),'');await page.evaluate(()=>(window as any).accessTest.approved=true);for(const request of [{operation:'fill' as const,target:editorTarget,value:'PRIVATE TEXT'},{operation:'fill' as const,target:fileTarget,value:attachment}]){const result=await execute(page,request);assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(result.url,undefined);assert(!JSON.stringify(result).includes('PRIVATE'));assert(result.values?.every(value=>value.value===undefined));}assert.equal(await page.locator('#edited').textContent(),'PRIVATE TEXT');assert.equal(await page.locator('#files').textContent(),'private.pdf');const metadata=await page.evaluate(async target=>(window as any).__angularMcpBridge.describe(target),editorTarget);assert(!JSON.stringify(metadata).includes('PRIVATE'));const audit=await page.evaluate(()=>(window as any).accessTest.audit);assert(!JSON.stringify(audit).includes('PRIVATE'));assert(!JSON.stringify(audit).includes('private.pdf'));await page.evaluate(()=>(window as any).accessTest.session=null);await assert.rejects(execute(page,{operation:'fill',target:editorTarget,value:'Revoked'}),/session|revoked/);assert.equal(await page.locator('#edited').textContent(),'PRIVATE TEXT');}finally{await page.close();}});

test('exact pointer drags invoke real Angular CDK reorder handlers without writing component state',async()=>{const page=await fresh();try{const nodes=await list(page),handle=nodes.find(node=>node.sourceId==='handle-Alpha')!,drop=nodes.find(node=>node.sourceId==='row-Gamma')!;assert(handle.operations.includes('drag'));const result=await execute(page,{operation:'drag',target:{instanceId:handle.instanceId},destination:{instanceId:drop.instanceId},position:'after'});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('#order').textContent(),'Beta,Gamma,Alpha');assert.equal(result.businessStatus,'unknown');const stale=await execute(page,{operation:'drag',target:{instanceId:handle.instanceId},destination:{instanceId:'missing'}});assert.equal(stale.status,'not-dispatched');assert.match(stale.reason!,/stale/);}finally{await page.close();}});

test('partially covered native inputs remain usable through an exposed interior point',async()=>{const page=await fresh();try{const field=(await list(page)).find(node=>node.label==='Partially covered field')!;const result=await execute(page,{operation:'fill',target:{instanceId:field.instanceId},value:'Visible portion'});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('#covered').textContent(),'Visible portion');}finally{await page.close();}});

test('production dragging requires approval and destination permission with both endpoints bound to the approved UI state',async()=>{for(const dropAllowed of [false,true]){const page=await fresh();try{const nodes=await list(page),source=nodes.find(node=>node.sourceId==='handle-Alpha')!,drop=nodes.find(node=>node.sourceId==='row-Gamma')!,policy={version:1 as const,allowedOrigins:[base],rules:[{sourceId:source.sourceId,label:'Move item',operations:['describe','drag'] as ('describe'|'drag')[]},{sourceId:drop.sourceId,label:'Destination',operations:dropAllowed?['describe','drag'] as ('describe'|'drag')[]:['describe'] as ('describe'|'drag')[]}]};const compiler=createRequire(import.meta.url)('typescript'),code=compiler.transpileModule(integrationProductionSource(policy,'drag-access-test'),{compilerOptions:{target:compiler.ScriptTarget.ES2022,module:compiler.ModuleKind.None}}).outputText;await page.addScriptTag({content:`var dragAccess={approved:false,mutate:false,session:{id:'drag-session',subject:'operator',expiresAt:Date.now()+60000}};var __ngxMcpConnectAccess=async()=>({session:dragAccess.session,origin:()=>location.origin,validateSession:async()=>dragAccess.session,approve:async()=>{if(dragAccess.mutate)window.__angularMcpBridge.element({sourceId:'row-Gamma'}).textContent='Changed destination';return dragAccess.approved;},audit:()=>{}});`+code});await page.waitForFunction(()=>(window as any).__angularMcpBridge.accessStatus().ready);const input={operation:'drag' as const,target:{instanceId:source.instanceId},destination:{instanceId:drop.instanceId},position:'after' as const};await assert.rejects(execute(page,input),/approval|authoriz|denied|destination/);assert.equal(await page.locator('#order').textContent(),'Alpha,Beta,Gamma');await page.evaluate(()=>(window as any).dragAccess.approved=true);if(!dropAllowed){await assert.rejects(execute(page,input),/authoriz|denied|destination/);assert.equal(await page.locator('#order').textContent(),'Alpha,Beta,Gamma');}else{await page.evaluate(()=>(window as any).dragAccess.mutate=true);await assert.rejects(execute(page,input),/state changed/);assert.equal(await page.locator('#order').textContent(),'Alpha,Beta,Gamma');}}finally{await page.close();}}});

test('an inline editor that closes on blur acknowledges the dispatched edit while its old identity remains stale',async()=>{const page=await fresh();try{const field=(await list(page)).find(node=>node.label==='Inline editor')!;const result=await execute(page,{operation:'fill',target:{instanceId:field.instanceId},value:'Committed edit'});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.match(result.reason!,/replaced/);assert.equal(await page.locator('#inline-saved').textContent(),'Committed edit');assert.equal(await page.getByRole('textbox',{name:'Inline editor'}).count(),0);await assert.rejects(execute(page,{operation:'fill',target:{instanceId:field.instanceId},value:'Stale'}),/stale/);}finally{await page.close();}});

test('catalog relationships identify forms and repeated row actions without DOM selectors',async()=>{const page=await fresh();try{const nodes=await list(page),form=nodes.find(node=>node.sourceId==='ownership-form')!;for(const label of ['Owned control','Owned Save'])assert.equal(nodes.find(node=>node.label===label&&node.kind!=='form')!.formTarget!.instanceId,form.instanceId);const row=nodes.find(node=>node.sourceId==='context-Second')!,action=nodes.find(node=>node.label==='Edit item'&&node.contextTarget?.instanceId===row.instanceId)!;assert(action);assert.equal((await execute(page,{operation:'activate',target:{instanceId:action.instanceId}})).status,'ui-dispatched');assert.equal(await page.locator('#selected').textContent(),'Second');}finally{await page.close();}});

test('same-origin iframe fields, forms, links and nested controls use their original document handlers',async()=>{const page=await fresh();try{await page.frameLocator('#native-frame').getByRole('button',{name:'Save frame'}).waitFor();const nodes=await list(page),field=nodes.find(node=>node.label==='Frame title'&&node.tagName==='input')!,form=nodes.find(node=>node.kind==='form'&&node.frameTarget?.sourceId==='fixture-frame')!,link=nodes.find(node=>node.label==='Frame link')!;assert(field);assert(form);assert(link);assert.equal(field.frameTarget?.sourceId,'fixture-frame');assert.equal((await execute(page,{operation:'fill',target:{instanceId:field.instanceId},value:'Saved in frame'})).status,'ui-dispatched');assert.equal((await execute(page,{operation:'submit',target:{instanceId:form.instanceId},values:[]})).status,'ui-dispatched');assert.equal(await page.frameLocator('#native-frame').locator('#frame-output').textContent(),'Saved in frame');assert.equal((await execute(page,{operation:'activate',target:{instanceId:link.instanceId}})).status,'ui-dispatched');assert.equal(await page.frameLocator('#native-frame').locator('body').getAttribute('data-followed'),'1');const nested=(await list(page)).find(node=>node.label==='Nested frame action')!;assert(nested);assert.equal((await execute(page,{operation:'activate',target:{instanceId:nested.instanceId}})).status,'ui-dispatched');assert.equal(await page.frameLocator('#native-frame').frameLocator('iframe').locator('body').getAttribute('data-result'),'1');assert(!(await list(page)).some(node=>node.label==='Foreign secret'));}finally{await page.close();}});
test('frame controls cannot bypass a parent overlay and their handles become stale after frame removal',async()=>{const page=await fresh();try{await page.frameLocator('#native-frame').getByRole('textbox',{name:'Frame title'}).waitFor();const field=(await list(page)).find(node=>node.label==='Frame title'&&node.tagName==='input')!,target={instanceId:field.instanceId};await page.evaluate(()=>{const overlay=document.createElement('div');overlay.id='frame-blocker';overlay.style.cssText='position:fixed;inset:0;z-index:2147483647;background:white';document.body.append(overlay);});const blocked=await execute(page,{operation:'fill',target,value:'Blocked'});assert.equal(blocked.status,'not-dispatched');assert.match(blocked.reason!,/covering/);assert.equal(await page.frameLocator('#native-frame').getByRole('textbox',{name:'Frame title'}).inputValue(),'');await page.locator('#frame-blocker').evaluate(node=>node.remove());await page.locator('#native-frame').evaluate(node=>(node as HTMLElement).style.transform='rotate(8deg)');assert.equal((await execute(page,{operation:'fill',target,value:'Rotated'})).status,'not-dispatched');assert.equal(await page.frameLocator('#native-frame').getByRole('textbox',{name:'Frame title'}).inputValue(),'');await page.locator('#native-frame').evaluate(node=>node.remove());assert(!(await list(page)).some(node=>node.instanceId===target.instanceId));await assert.rejects(execute(page,{operation:'fill',target,value:'Stale'}),/stale/);}finally{await page.close();}});
test('authored SVG clicks dispatch the original Angular listener',async()=>{const page=await fresh();try{const result=await execute(page,{operation:'activate',target:{sourceId:'svg-action'}});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('#selected').textContent(),'svg');}finally{await page.close();}});

test('UI dispatch preserves the original event listener zone and browser default-action timing',async()=>{const page=await fresh();try{await page.addScriptTag({content:"const input=document.createElement('input');input.setAttribute('aria-label','Zoned input');document.body.append(input);window.zoneEntries=0;window.insideZone=false;input.addEventListener('input',()=>window.eventInsideZone=window.insideZone);window.__angularMcpBridge.register('zoned-input',input,null,null,null,undefined,undefined,{run:(callback)=>{window.zoneEntries++;const previous=window.insideZone;window.insideZone=true;try{return callback();}finally{window.insideZone=previous;}}});"});const result=await execute(page,{operation:'fill',target:{sourceId:'zoned-input'},value:'In zone'});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.getByRole('textbox',{name:'Zoned input'}).inputValue(),'In zone');assert.equal(await page.evaluate(()=>(window as any).zoneEntries),1);assert.equal(await page.evaluate(()=>(window as any).eventInsideZone),false);}finally{await page.close();}});

test('allowing a frame host does not grant production access to native child controls',async()=>{const page=await fresh();try{await page.frameLocator('#native-frame').getByRole('textbox',{name:'Frame title'}).waitFor();const child=(await list(page)).find(node=>node.label==='Frame title'&&node.tagName==='input')!,policy={version:1 as const,allowedOrigins:[base],rules:[{sourceId:'fixture-frame',label:'Preview frame',operations:['describe','activate'] as ('describe'|'activate')[]}]};const compiler=createRequire(import.meta.url)('typescript'),code=compiler.transpileModule(integrationProductionSource(policy,'frame-access-test'),{compilerOptions:{target:compiler.ScriptTarget.ES2022,module:compiler.ModuleKind.None}}).outputText;await page.addScriptTag({content:`var __ngxMcpConnectAccess=async()=>{const session={id:'frame-session',subject:'operator',expiresAt:Date.now()+60000};return {session,origin:()=>location.origin,validateSession:async()=>session,approve:async()=>true,audit:()=>{}}};`+code});await page.waitForFunction(()=>(window as any).__angularMcpBridge.accessStatus().ready);const catalog=await page.evaluate(()=>(window as any).__angularMcpBridge.catalog());assert(catalog.some((node:any)=>node.sourceId==='fixture-frame'));assert(!catalog.some((node:any)=>node.instanceId===child.instanceId));await assert.rejects(execute(page,{operation:'fill',target:{instanceId:child.instanceId},value:'Denied'}),/denied/);assert.equal(await page.frameLocator('#native-frame').getByRole('textbox',{name:'Frame title'}).inputValue(),'');}finally{await page.close();}});

test('multiple compiled aliases for one native input produce one form schema field and one original save',async()=>{const page=await fresh();try{const nodes=await list(page),form=nodes.find(node=>node.sourceId==='alias-form')!;assert.equal(form.fields!.length,1);assert.equal(form.fields![0]!.sourceId,'alias-host');const tool=integrationFormTools([form],id=>'form-'+id)[0]!;assert(tool);assert.deepEqual(Object.keys(tool.inputSchema.properties as object),['alias']);const result=await execute(page,{operation:'submit',target:{instanceId:form.instanceId},values:[{target:{instanceId:form.fields![0]!.instanceId},value:'Shared model'}]});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.equal(await page.locator('#alias-saved').textContent(),'Shared model');}finally{await page.close();}});

test('explicit keyboard activation supports pointer-inaccessible frame links and honors modal focus boundaries',async()=>{const page=await fresh();try{await page.frameLocator('#native-frame').getByRole('link',{name:'Frame link'}).waitFor();await page.locator('#native-frame').evaluate(node=>(node as HTMLElement).style.pointerEvents='none');const link=(await list(page)).find(node=>node.label==='Frame link')!,target={instanceId:link.instanceId};assert.equal((await execute(page,{operation:'activate',target,event:'keyboard',key:'Enter'})).status,'ui-dispatched');assert.equal(await page.frameLocator('#native-frame').locator('body').getAttribute('data-followed'),'1');await page.evaluate(()=>{const modal=document.createElement('div');modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.textContent='Modal';modal.style.cssText='position:fixed;inset:0;background:white';document.body.append(modal);});const blocked=await execute(page,{operation:'activate',target,event:'keyboard',key:'Enter'});assert.equal(blocked.status,'not-dispatched');assert.match(blocked.reason!,/modal/);}finally{await page.close();}});

test('zoned Angular cancel preserves browser default-submit ordering and never invokes the removed form',async()=>{const outcomes=[];for(const mode of ['browser','bridge']){const page=await browser.newPage();try{await page.goto(base+'/zoned');await page.locator('[angularMcpSource="cancel"][data-angular-mcp-instance]').waitFor();if(mode==='browser')await page.getByRole('button',{name:'Cancel'}).click();else{const result=await execute(page,{operation:'activate',target:{sourceId:'cancel'}});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));}await page.locator('form').waitFor({state:'detached'});outcomes.push(await page.locator('output').textContent());}finally{await page.close();}}assert.deepEqual(outcomes,['0','0']);});

test('a visually exposed authored icon can activate despite decorative ARIA while hidden containers remain unavailable',async()=>{const page=await fresh();try{const nodes=await list(page),icon=nodes.find(node=>node.sourceId==='decorative-authored')!,hidden=nodes.find(node=>node.sourceId==='hidden-container')!,passive=nodes.find(node=>node.sourceId==='decorative-passive')!;assert.equal(icon.visible,true);assert.equal(hidden.visible,false);assert.equal(passive.visible,false);const result=await execute(page,{operation:'activate',target:{instanceId:icon.instanceId}});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));await page.waitForFunction(()=>document.querySelector('#selected')?.textContent==='decorative');const refused=await execute(page,{operation:'activate',target:{instanceId:hidden.instanceId}});assert.equal(refused.status,'not-dispatched');assert.equal(await page.locator('#selected').textContent(),'decorative');}finally{await page.close();}});

test('Angular public event registrations expose library pointer commands without ARIA semantics or component access',async()=>{const page=await fresh();try{const node=(await list(page)).find(node=>node.label==='Library mouse command')!;assert(node);assert.equal(node.provenance,'runtime-dom');assert(node.events.includes('mousedown'));assert(node.operations.includes('activate'));const result=await execute(page,{operation:'activate',target:{instanceId:node.instanceId},event:'mousedown'});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));await page.waitForFunction(()=>document.querySelector('#selected')?.textContent==='mouse-command');await page.locator('[title="Library mouse command"]').evaluate(node=>node.remove());assert(!(await list(page)).some(current=>current.instanceId===node.instanceId));await assert.rejects(execute(page,{operation:'activate',target:{instanceId:node.instanceId},event:'mousedown'}),/missing|stale/);}finally{await page.close();}});

test('exact text selection and observed formatting commands preserve original browser editing events',async()=>{const page=await fresh();try{const target=await domTarget(page,'Library rich editor');await execute(page,{operation:'fill',target,value:'Selected formatting'});const selected=await execute(page,{operation:'activate',target,event:'select-all'});assert.equal(selected.status,'ui-dispatched',JSON.stringify(selected));assert.equal(await page.evaluate(()=>window.getSelection()?.toString()),'Selected formatting');const command=(await list(page)).find(node=>node.label==='Library strong command')!;const result=await execute(page,{operation:'activate',target:{instanceId:command.instanceId},event:'mousedown'});assert.equal(result.status,'ui-dispatched',JSON.stringify(result));assert.match(await page.locator('#edited').textContent()||'',/<(?:b|strong)>Selected formatting<\/(?:b|strong)>/);const refused=await execute(page,{operation:'activate',target:{sourceId:'open-snack'},event:'select-all'});assert.equal(refused.status,'not-dispatched');}finally{await page.close();}});

test('transparent editor delegates expose selection and replace saved text after the original selection observer settles',async()=>{const page=await fresh();try{const node=(await list(page)).find(node=>node.sourceId==='cached-editor')!;assert(node.operations.includes('activate'));const target={instanceId:node.instanceId};const filled=await execute(page,{operation:'fill',target,value:'Replacement text'});assert.equal(filled.status,'ui-dispatched',JSON.stringify(filled));assert.equal(await page.locator('#cached-value').textContent(),'Replacement text');const selected=await execute(page,{operation:'activate',target,event:'select-all'});assert.equal(selected.status,'ui-dispatched',JSON.stringify(selected));assert.equal(await page.evaluate(()=>window.getSelection()?.toString()),'Replacement text');}finally{await page.close();}});

test('catalog field labels preserve public references and mark unambiguous single-control context without choosing between labels',async()=>{const page=await fresh();try{const nodes=await list(page),url=nodes.find(node=>node.tagName==='input'&&node.label==='Library URL')!,reference=nodes.find(node=>node.tagName==='input'&&node.label==='Referenced library title')!,hint=nodes.find(node=>node.tagName==='input'&&node.label==='Explicit hint')!;assert(url);assert.equal(url.labelSource,'single-control-context');assert.equal(reference.labelSource,'aria-labelledby');assert.equal(hint.labelSource,'placeholder');assert(!nodes.some(node=>node.tagName==='input'&&['First ambiguous','Second ambiguous'].includes(node.label)));}finally{await page.close();}});
